create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_PRODUCT (
	PROD_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record, i.e. where the current date is between dwh_valid_from and dwh_valid_to.',
	PROD_NR VARCHAR(20) NOT NULL COMMENT 'The number which (globally) identifies the product within the organization. (Note that the product number is unique for a certain point in time, but may be re-used later on.)',
	PROD_NAME VARCHAR(250) NOT NULL COMMENT 'The (global) name by which the product is marketed.',
	PROD_DESCR VARCHAR(250) COMMENT 'A more detailed (free text) description for the product.',
	PROD_CREATION_DT DATE COMMENT 'The date when product was first listed.',
	PROD_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the discriminator for products.',
	PROD_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the discriminator for products. (Description in group language, i.e. in German)',
	ITEM_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the subtype discriminator for items.',
	ITEM_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the subtype discriminator for items. (Description in group language, i.e. in German)',
	PROD_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the general lifecycle status for products.',
	PROD_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the general lifecycle status for products. (Description in group language, i.e. in German)',
	PROD_BUYING_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the buying status for products.',
	PROD_BUYING_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the buying status for products. (Description in group language, i.e. in German)',
	PROD_DESIGN_STATUS_CD VARCHAR(20) NOT NULL COMMENT 'The code for the design status for products.',
	PROD_DESIGN_STATUS_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the design status for products. (Description in group language, i.e. in German)',
	PACKING_TYPE_CD VARCHAR(20) NOT NULL COMMENT 'The code identifying the way, how a product is packed.',
	PACKING_TYPE_DESCR VARCHAR(250) NOT NULL COMMENT 'A textual description for the way how a product is packed. (Description in group language, i.e. in German)',
	GOODS_ON_CONSIGNMENT_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product is sold on behalf of a third party. Sales revenue is directly transferred to this third party, who in turn, pays a commisson to the vending party.',
	EXCL_FROM_VAT_CALC_FG BOOLEAN NOT NULL COMMENT 'An indidcator showing, if the product should be excluded from the VAT calculation.',
	COUNTRY_SPECIFIC_PROD_FG BOOLEAN NOT NULL COMMENT 'An indicator showing, if the product has been defined by only one country organization and is therefore available only in one country. (This does not include products, which are defined globally, but which happen to be sold in only one country.)',
	SPECIFIC_COUNTRY_ORG_SID NUMBER(38,0) NOT NULL COMMENT 'In case of a country specific product this is the country organization in which the product exists.',
	SPECIFIC_COUNTRY_ORG_CD VARCHAR(2) COMMENT 'In case of a country specific product this is the code of the country organization in which the product exists.',
	ITEM_FAM_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the item family to which this product belongs.',
	ITEM_FAM_NR VARCHAR(100) COMMENT 'The number by which the related item family is known to business.',
	ITEM_FAM_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the item family. (Name in group language, i.e. in German)',
	SUB_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for a sub item group to which this product belongs.',
	SUB_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related sub item group is known to business.',
	SUB_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the sub item group. (Name in group language, i.e. in German)',
	FOOD_FG BOOLEAN NOT NULL COMMENT 'An indicator distinguishing food from non-food items.',
	INT_ITEM_GRP_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier [surrogate key] for an international item group to which this product belongs',
	INT_ITEM_GRP_NR VARCHAR(100) COMMENT 'The number by which the related international item group is known to business.',
	INT_ITEM_GRP_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the international item group. (Name in group language, i.e. in German)',
	PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the pillar, to which this product belongs.',
	PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related pillar is known to business.',
	PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the pillar.(Name in group language, i.e. in German)',
	MAIN_PILLAR_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the main pillar, to which this product belongs.',
	MAIN_PILLAR_NR VARCHAR(100) COMMENT 'The number by which the related main pillar is known to business.',
	MAIN_PILLAR_NAME VARCHAR(100) NOT NULL COMMENT 'The name of the main pillar. (Name in group language, i.e. in German)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_PRODUCT primary key (PROD_SID, DWH_VALID_FROM_TMSP)
)COMMENT='The term „Product\"" describes goods and services which are offered by the enterprise. In the case of a retailer these are the goods the company trades with. The term “product” is not limited to the current assortment of goods and services, but may also include articles of competitors or articles which are currently not in the assortment.'
;